     1→import { animateParallel, Block, Text } from "@prototyp/skeletor";
     2→import { useAtom } from "jotai";
     3→import { RoomService } from "modules/room/service/RoomService";
     4→import { TimelineAtoms } from "modules/timeline/jotai";
     5→import { TimelineService } from "modules/timeline/service/TimelineService";
     6→import { type FC, useEffect, useState } from "react";
     7→import { Image } from "react-native";
     8→import { Button, Input } from "shared/components";
     9→import { Colors } from "shared/styles";
    10→import { InputMessagePayload } from "../input-message-payload";
    11→import { SendItemsList } from "../send-items-list";
    12→import { VoiceRecordButton } from "../voice-record-button";
    13→
    14→interface Props {
    15→  roomId: string;
    16→}
    17→
    18→const sendButtonTransition = animateParallel(
    19→  { opacity: [0, 1], width: [0, 56] },
    20→  { duration: 200, native: false },
    21→);
    22→
    23→const imageTransition = animateParallel(
    24→  { opacity: [0, 1], width: [0, 48] },
    25→  { duration: 200, native: false },
    26→);
    27→
    28→const inputTransition = animateParallel(
    29→  { opacity: [0, 1], width: ["0%", "100%"] },
    30→  { duration: 200, native: false },
    31→);
    32→
    33→export const RoomInput: FC<Props> = ({ roomId }) => {
    34→  const [message, setMessage] = useState("");
    35→  const [isRecording, setIsRecording] = useState(false);
    36→  const [isRecorded, setIsRecorded] = useState(false);
    37→  const [canSend, setCanSend] = useState(true);
    38→
    39→  useEffect(() => {
    40→    Promise.all([
    41→      RoomService.getUserPowerLevel(roomId),
    42→      RoomService.getRoomPowerLevels(roomId),
    43→    ])
    44→      .then(([userLevel, pl]) => {
    45→        const sendLevel = pl ? Number(pl.values().eventsDefault) : 0;
    46→        setCanSend((userLevel ?? 0) >= sendLevel);
    47→      })
    48→      .catch(console.error);
    49→  }, [roomId]);
    50→  const [replyPayload, setReplyPayload] = useAtom(TimelineAtoms.replyPayload);
    51→  const [editPayload, setEditPayload] = useAtom(TimelineAtoms.editPayload);
    52→  const hasPayload = !!replyPayload || !!editPayload;
    53→
    54→  const handleSendMessage = async () => {
    55→    if (!message) return;
    56→
    57→    try {
    58→      if (editPayload) {
    59→        await TimelineService.editMessage(roomId, editPayload.event, message);
    60→        setEditPayload(null);
    61→        return;
    62→      }
    63→
    64→      if (replyPayload) {
    65→        await TimelineService.replyToMessage(
    66→          roomId,
    67→          message,
    68→          replyPayload.eventId,
    69→        );
    70→        setReplyPayload(null);
    71→        return;
    72→      }
    73→
    74→      await TimelineService.sendMessage(roomId, message);
    75→    } catch (error) {
    76→      console.error("Failed to send message:", error);
    77→    } finally {
    78→      setMessage("");
    79→    }
    80→  };
    81→
    82→  useEffect(() => {
    83→    if (!editPayload) {
    84→      setMessage("");
    85→      return;
    86→    }
    87→    setMessage(editPayload.content);
    88→  }, [editPayload]);
    89→
    90→  useEffect(() => {
    91→    if (message || replyPayload) {
    92→      sendButtonTransition.start();
    93→      imageTransition.reverse();
    94→    } else {
    95→      sendButtonTransition.reverse();
    96→      imageTransition.start();
    97→    }
    98→  }, [message, replyPayload]);
    99→
   100→  useEffect(() => {
   101→    setReplyPayload(null);
   102→    setEditPayload(null);
   103→  }, [setEditPayload, setReplyPayload]);
   104→
   105→  useEffect(() => {
   106→    if (isRecording || isRecorded) {
   107→      imageTransition.reverse();
   108→      inputTransition.reverse();
   109→    } else {
   110→      imageTransition.start();
   111→      inputTransition.start();
   112→    }
   113→  }, [isRecording, isRecorded]);
   114→
   115→  if (!canSend) {
   116→    return (
   117→      <Block paddings={20} flexDirection="row" align="center" gap={8}>
   118→        <Image
   119→          source={require("assets/icons/warning.png")}
   120→          width={24}
   121→          height={24}
   122→          tintColor={Colors.white80}
   123→        />
   124→        <Text color={Colors.white80}>
   125→          You don't have permission to send messages
   126→        </Text>
   127→      </Block>
   128→    );
   129→  }
   130→
   131→  return (
   132→    <Block>
   133→      <Block
   134→        paddings={[20, 0, 20, 16]}
   135→        flexDirection="row"
   136→        align="flex-end"
   137→        justify="space-between"
   138→        height={hasPayload ? 158 : 88}
   139→        gap={message || replyPayload ? 0 : 8}
   140→      >
   141→        <Block
   142→          animations={imageTransition.animations}
   143→          height={48}
   144→          align="center"
   145→          justify="center"
   146→        >
   147→          <SendItemsList roomId={roomId} />
   148→        </Block>
   149→        <VoiceRecordButton
   150→          roomId={roomId}
   151→          message={message}
   152→          isRecording={isRecording}
   153→          isRecorded={isRecorded}
   154→          setIsRecorded={setIsRecorded}
   155→          setIsRecording={setIsRecording}
   156→        />
   157→        <Block
   158→          flex={isRecording || isRecorded ? 0 : 1}
   159→          animations={inputTransition.animations}
   160→          border={{ borderRadius: hasPayload ? 12 : 40 }}
   161→          background={Colors.white5}
   162→        >
   163→          <InputMessagePayload />
   164→          <Input
   165→            placeholder="Message"
   166→            value={message}
   167→            background="transparent"
   168→            autoCapitalize="none"
   169→            onChangeText={(value) => setMessage(value)}
   170→          />
   171→        </Block>
   172→        <Block
   173→          animations={sendButtonTransition.animations}
   174→          height={48}
   175→          overflow="hidden"
   176→        >
   177→          <Button.Wrapper disabled={!message} onPress={handleSendMessage}>
   178→            <Block
   179→              height={48}
   180→              width={48}
   181→              align="center"
   182→              justify="center"
   183→              background={Colors.primary}
   184→              border={{
   185→                borderRadius: 24,
   186→              }}
   187→              margins={{ marginLeft: 8 }}
   188→            >
   189→              <Image
   190→                source={require("assets/icons/paper-plane-right.png")}
   191→                width={24}
   192→                height={24}
   193→              />
   194→            </Block>
   195→          </Button.Wrapper>
   196→        </Block>
   197→      </Block>
   198→    </Block>
   199→  );
   200→};
   201→

