     1→import { Block, Text } from "@prototyp/skeletor";
     2→import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
     3→import { useAtom } from "jotai";
     4→import {
     5→  addDateDividers,
     6→  getEventId,
     7→  getItemUniqueKey,
     8→} from "modules/matrix-client/utils";
     9→import { useRoomTimeline } from "modules/timeline/hooks";
    10→import { TimelineAtoms } from "modules/timeline/jotai";
    11→import {
    12→  filterSameStateKey,
    13→  handleIsPreviousSameSender,
    14→} from "modules/timeline/utils";
    15→import {
    16→  type FC,
    17→  useCallback,
    18→  useEffect,
    19→  useMemo,
    20→  useRef,
    21→  useState,
    22→} from "react";
    23→import {
    24→  FlatList,
    25→  Image,
    26→  KeyboardAvoidingView,
    27→  type NativeScrollEvent,
    28→  type NativeSyntheticEvent,
    29→  StyleSheet,
    30→} from "react-native";
    31→import {
    32→  Button,
    33→  ImageViewerModal,
    34→  Loading,
    35→  MemberDetailsBottomSheet,
    36→  VideoViewerModal,
    37→} from "shared/components";
    38→import { useMemberDetails } from "shared/hooks";
    39→import { DateDivider } from "../date-divider";
    40→import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
    41→import { RoomInput } from "../room-input";
    42→import { SingleMessageType } from "../single-message-type";
    43→
    44→interface Props {
    45→  room: RoomInterface;
    46→  roomId: string;
    47→}
    48→
    49→export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
    50→  const flatListRef = useRef<FlatList>(null);
    51→  const isAtBottomRef = useRef(true);
    52→  const [showScrollDown, setShowScrollDown] = useState(false);
    53→  const {
    54→    events,
    55→    loadingMessage,
    56→    refreshing,
    57→    updateTrigger,
    58→    isDirect,
    59→    loadMoreMessages,
    60→    markAsRead,
    61→  } = useRoomTimeline({
    62→    room,
    63→    roomId,
    64→  });
    65→  const [scrollToEventId, setScrollToEventId] = useAtom(
    66→    TimelineAtoms.scrollToEventId,
    67→  );
    68→  const {
    69→    selectedMember,
    70→    isBottomSheetOpen,
    71→    openMemberDetails,
    72→    closeMemberDetails,
    73→  } = useMemberDetails();
    74→
    75→  const sortedEvents = useMemo(() => {
    76→    const sorted = [...events].sort(
    77→      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    78→    );
    79→
    80→    return filterSameStateKey(sorted);
    81→  }, [events]);
    82→
    83→  const eventsWithDividers = useMemo(() => {
    84→    return addDateDividers(sortedEvents);
    85→  }, [sortedEvents]);
    86→
    87→  const handleScrollToEvent = useCallback(
    88→    (eventId: string) => {
    89→      const index = eventsWithDividers.findIndex(
    90→        (item) => item.type === "event" && getEventId(item.data) === eventId,
    91→      );
    92→      if (index === -1) return;
    93→
    94→      flatListRef.current?.scrollToIndex({
    95→        index,
    96→        animated: true,
    97→        viewPosition: 0.5,
    98→      });
    99→    },
   100→    [eventsWithDividers],
   101→  );
   102→
   103→  useEffect(() => {
   104→    if (!scrollToEventId) return;
   105→    handleScrollToEvent(scrollToEventId);
   106→    setScrollToEventId(null);
   107→  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
   108→
   109→  const handleLoadMore = async () => {
   110→    setShowScrollDown(false);
   111→    await loadMoreMessages();
   112→  };
   113→
   114→  const handleContentSizeChange = () => {
   115→    const lastEvent = sortedEvents[sortedEvents.length - 1];
   116→    if (!isAtBottomRef.current && !lastEvent?.isOwn) return;
   117→    flatListRef.current?.scrollToEnd({ animated: false });
   118→    setTimeout(() => {
   119→      flatListRef.current?.scrollToEnd({ animated: false });
   120→    }, 100);
   121→  };
   122→
   123→  const handleScrollDown = () => {
   124→    flatListRef.current?.scrollToEnd({ animated: true });
   125→    setShowScrollDown(false);
   126→  };
   127→
   128→  const handleOnScroll = ({
   129→    nativeEvent,
   130→  }: NativeSyntheticEvent<NativeScrollEvent>) => {
   131→    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
   132→    const paddingToBottom = 100;
   133→    const atBottom =
   134→      layoutMeasurement.height + contentOffset.y >=
   135→      contentSize.height - paddingToBottom;
   136→    isAtBottomRef.current = atBottom;
   137→    if (!atBottom) return;
   138→    setShowScrollDown(false);
   139→    markAsRead();
   140→  };
   141→
   142→  useEffect(() => {
   143→    const lastEvent = sortedEvents[sortedEvents.length - 1];
   144→    if (isAtBottomRef.current || lastEvent?.isOwn) return;
   145→
   146→    setShowScrollDown(true);
   147→  }, [isAtBottomRef.current, sortedEvents]);
   148→
   149→  if (loadingMessage) {
   150→    return (
   151→      <Block flex={1} align="center" justify="center">
   152→        <Loading isFullScreen={false} />
   153→      </Block>
   154→    );
   155→  }
   156→
   157→  return (
   158→    <>
   159→      <KeyboardAvoidingView style={styles.flex} behavior="padding">
   160→        <FlatList
   161→          ref={flatListRef}
   162→          data={eventsWithDividers}
   163→          keyExtractor={(item) => {
   164→            if (item.type === "divider") return item.id;
   165→
   166→            return getItemUniqueKey(item.data) ?? "";
   167→          }}
   168→          extraData={updateTrigger}
   169→          contentContainerStyle={styles.listContent}
   170→          refreshing={refreshing}
   171→          onContentSizeChange={handleContentSizeChange}
   172→          onRefresh={handleLoadMore}
   173→          onScroll={handleOnScroll}
   174→          onScrollToIndexFailed={(info) => {
   175→            flatListRef.current?.scrollToOffset({
   176→              offset: info.averageItemLength * info.index,
   177→              animated: true,
   178→            });
   179→          }}
   180→          renderItem={({ item }) => {
   181→            if (item.type === "divider") {
   182→              return <DateDivider date={item.date} />;
   183→            }
   184→
   185→            const itemKey = getItemUniqueKey(item.data);
   186→            const eventIndex = sortedEvents.findIndex(
   187→              (e) => getItemUniqueKey(e) === itemKey,
   188→            );
   189→
   190→            return (
   191→              <SingleMessageType
   192→                event={item.data}
   193→                isPreviousSameSender={handleIsPreviousSameSender(
   194→                  isDirect,
   195→                  sortedEvents,
   196→                  item.data,
   197→                  eventIndex,
   198→                )}
   199→                onMemberPress={openMemberDetails}
   200→              />
   201→            );
   202→          }}
   203→        />
   204→
   205→        <RoomInput roomId={roomId} />
   206→      </KeyboardAvoidingView>
   207→
   208→      <MessageContentBottomSheet roomId={roomId} />
   209→
   210→      <MemberDetailsBottomSheet
   211→        isBottomSheetOpen={isBottomSheetOpen}
   212→        selectedMember={selectedMember}
   213→        roomId={roomId}
   214→        onClose={closeMemberDetails}
   215→      />
   216→
   217→      {showScrollDown && (
   218→        <Block
   219→          absolute
   220→          offsets={{ right: 0, bottom: 100 }}
   221→          align="center"
   222→          justify="center"
   223→          width="100%"
   224→        >
   225→          <Button.Outline size="medium" onPress={handleScrollDown}>
   226→            <Text>New messages</Text>
   227→            <Image source={require("assets/icons/arrow-down.png")} />
   228→          </Button.Outline>
   229→        </Block>
   230→      )}
   231→
   232→      <ImageViewerModal />
   233→      <VideoViewerModal />
   234→    </>
   235→  );
   236→};
   237→
   238→const styles = StyleSheet.create({
   239→  flex: {
   240→    flex: 1,
   241→  },
   242→  listContent: {
   243→    paddingHorizontal: 20,
   244→    paddingTop: 12,
   245→    paddingBottom: 20,
   246→  },
   247→});
   248→

