     1→import type { DocumentPickerResponse } from "@react-native-documents/picker";
     2→import {
     3→  type AudioMessageContent,
     4→  EditedContent,
     5→  type EventTimelineItem,
     6→  type FileMessageContent,
     7→  type ImageMessageContent,
     8→  MessageType_Tags,
     9→  MsgLikeKind_Tags,
    10→  TimelineItemContent_Tags,
    11→  type UploadParameters,
    12→  UploadSource,
    13→  type VideoMessageContent,
    14→  messageEventContentFromMarkdown,
    15→} from "@unomed/react-native-matrix-sdk";
    16→import { MatrixCore } from "../../matrix-client/services/MatrixCore";
    17→import { getEventId } from "../../matrix-client/utils";
    18→
    19→export type ForwardMessageType = "text" | "image" | "video" | "audio" | "file";
    20→
    21→export class TimelineService {
    22→  public static sendMessage = async (roomId: string, message: string) => {
    23→    const room = MatrixCore.getRoom(roomId);
    24→    const timeline = await room.timeline();
    25→    if (!timeline) throw new Error("Timeline not found");
    26→    const messageContent = messageEventContentFromMarkdown(message);
    27→    await timeline.send(messageContent);
    28→  };
    29→
    30→  public static replyToMessage = async (
    31→    roomId: string,
    32→    message: string,
    33→    eventId: string,
    34→  ) => {
    35→    const room = MatrixCore.getRoom(roomId);
    36→    const timeline = await room.timeline();
    37→    if (!timeline) throw new Error("Timeline not found");
    38→    const messageContent = messageEventContentFromMarkdown(message);
    39→    await timeline.sendReply(messageContent, eventId);
    40→  };
    41→
    42→  public static editMessage = async (
    43→    roomId: string,
    44→    event: EventTimelineItem,
    45→    message: string,
    46→  ) => {
    47→    const room = MatrixCore.getRoom(roomId);
    48→    const timeline = await room.timeline();
    49→    if (!timeline) throw new Error("Timeline not found");
    50→
    51→    if (!event.eventOrTransactionId) {
    52→      throw new Error("Event is missing event or transaction id");
    53→    }
    54→
    55→    const messageContent = messageEventContentFromMarkdown(message);
    56→    const editedContent = EditedContent.RoomMessage.new({ content: messageContent });
    57→    await timeline.edit(event.eventOrTransactionId, editedContent);
    58→  };
    59→
    60→  public static reportMessage = async (
    61→    roomId: string,
    62→    event: EventTimelineItem,
    63→    reason: string,
    64→  ) => {
    65→    const room = MatrixCore.getRoom(roomId);
    66→    const eventId = getEventId(event);
    67→    if (!eventId) throw new Error("Event is missing event id");
    68→    await room.reportContent(eventId, undefined, reason);
    69→  };
    70→
    71→  public static deleteMessage = async (
    72→    roomId: string,
    73→    event: EventTimelineItem,
    74→  ) => {
    75→    const room = MatrixCore.getRoom(roomId);
    76→    const eventId = getEventId(event);
    77→    if (!eventId) throw new Error("Event is missing event id");
    78→    await room.redact(eventId, undefined);
    79→  };
    80→
    81→  public static forwardMessage = async (
    82→    roomId: string,
    83→    event: EventTimelineItem,
    84→    messageType: ForwardMessageType,
    85→  ) => {
    86→    const client = MatrixCore.getClient();
    87→    const room = MatrixCore.getRoom(roomId);
    88→    const timeline = await room.timeline();
    89→    if (!timeline) throw new Error("Timeline not found");
    90→
    91→    if (messageType === "text") {
    92→      const textContent = TimelineService.getTextContent(event);
    93→      if (!textContent) throw new Error("Text content not found");
    94→      await timeline.send(messageEventContentFromMarkdown(textContent));
    95→      return;
    96→    }
    97→
    98→    if (messageType === "image") {
    99→      const imageContent = TimelineService.getImageContent(event);
   100→      if (!imageContent) throw new Error("Image content not found");
   101→
   102→      const mediaFile = await client.getMediaFile(
   103→        imageContent.source,
   104→        imageContent.filename,
   105→        imageContent.info?.mimetype || "image/jpeg",
   106→        true,
   107→        undefined,
   108→      );
   109→      const filePath = mediaFile.path();
   110→      const fileSource: UploadParameters = {
   111→        source: new UploadSource.File({ filename: filePath }),
   112→        caption: imageContent.caption || undefined,
   113→        formattedCaption: undefined,
   114→        mentions: undefined,
   115→        inReplyTo: undefined,
   116→      };
   117→      const imageHandle = timeline.sendImage(
   118→        fileSource,
   119→        new UploadSource.File({ filename: filePath }),
   120→        {
   121→          height: imageContent.info?.height || BigInt(0),
   122→          width: imageContent.info?.width || BigInt(0),
   123→          mimetype: imageContent.info?.mimetype || "image/jpeg",
   124→          size: imageContent.info?.size || BigInt(0),
   125→          thumbnailInfo: imageContent.info?.thumbnailInfo,
   126→          thumbnailSource: undefined,
   127→          blurhash: imageContent.info?.blurhash || "",
   128→          isAnimated: false,
   129→        },
   130→      );
   131→      await imageHandle.join();
   132→      return;
   133→    }
   134→
   135→    if (messageType === "video") {
   136→      const videoContent = TimelineService.getVideoContent(event);
   137→      if (!videoContent) throw new Error("Video content not found");
   138→
   139→      const mediaFile = await client.getMediaFile(
   140→        videoContent.source,
   141→        videoContent.filename,
   142→        videoContent.info?.mimetype || "video/mp4",
   143→        true,
   144→        undefined,
   145→      );
   146→      const filePath = mediaFile.path();
   147→      const fileSource: UploadParameters = {
   148→        source: new UploadSource.File({ filename: filePath }),
   149→        caption: videoContent.caption || undefined,
   150→        formattedCaption: undefined,
   151→        mentions: undefined,
   152→        inReplyTo: undefined,
   153→      };
   154→      const videoHandle = timeline.sendVideo(
   155→        fileSource,
   156→        new UploadSource.File({ filename: filePath }),
   157→        {
   158→          height: videoContent.info?.height || BigInt(0),
   159→          width: videoContent.info?.width || BigInt(0),
   160→          mimetype: videoContent.info?.mimetype || "video/mp4",
   161→          size: videoContent.info?.size || BigInt(0),
   162→          duration: videoContent.info?.duration || 0,
   163→          thumbnailInfo: videoContent.info?.thumbnailInfo,
   164→          thumbnailSource: undefined,
   165→          blurhash: videoContent.info?.blurhash || "",
   166→        },
   167→      );
   168→      await videoHandle.join();
   169→      return;
   170→    }
   171→
   172→    if (messageType === "audio") {
   173→      const audioContent = TimelineService.getAudioContent(event);
   174→      if (!audioContent) throw new Error("Audio content not found");
   175→
   176→      const mediaFile = await client.getMediaFile(
   177→        audioContent.source,
   178→        audioContent.filename,
   179→        audioContent.info?.mimetype || "audio/mpeg",
   180→        true,
   181→        undefined,
   182→      );
   183→      const filePath = mediaFile.path();
   184→      const fileSource: UploadParameters = {
   185→        source: new UploadSource.File({ filename: filePath }),
   186→        caption: undefined,
   187→        formattedCaption: undefined,
   188→        mentions: undefined,
   189→        inReplyTo: undefined,
   190→      };
   191→      const audioHandle = timeline.sendAudio(fileSource, {
   192→        mimetype: audioContent.info?.mimetype || "audio/mpeg",
   193→        size: audioContent.info?.size || BigInt(0),
   194→        duration: audioContent.info?.duration || 0,
   195→      });
   196→      await audioHandle.join();
   197→      return;
   198→    }
   199→
   200→    if (messageType === "file") {
