     9→export const getMessageTextContent = (content: TimelineItemContent): string => {
    10→  if (content.tag === TimelineItemContent_Tags.MsgLike) {
    11→    const kind = content.inner.content.kind;
    12→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    13→      const msgType = kind.inner.content.msgType;
    14→
    15→      if (msgType?.tag === MessageType_Tags.Text) {
    16→        return kind.inner.content.body;
    17→      }
    18→
    19→      if (msgType?.tag === MessageType_Tags.Image) {
    20→        return msgType.inner.content.filename;
    21→      }
    22→
    23→      if (msgType?.tag === MessageType_Tags.Video) {
    24→        return msgType.inner.content.filename;
    25→      }
    26→
    27→      if (msgType?.tag === MessageType_Tags.Audio) {
    28→        return msgType.inner.content.filename;
    29→      }
    30→
    31→      return kind.inner.content.body;
    32→    }
    33→  }
    34→
    35→  return "";
    36→};
